"""Editorial portfolio collections based on visible features, not unverified site identities."""
from html import escape
COLLECTIONS = [
 dict(slug='architecture-and-greenery', title='Architecture, softened.', category='gardens', label='Architectural landscapes', cover='architectural-garden', lead='A precise line. A living edge. A landscape that lets the architecture breathe.', text='A generous lawn creates a quiet foreground for the building beyond. Clipped planting brings rhythm to the façade, while palms and softer foliage add a natural counterpoint to stone and glass.', detail='Explore the relationship between open green space, structured planting and the built environment. The result is a setting with clarity, depth and room to pause.', tags=['Open lawns','Structured planting','Architectural edges'], images=[('architectural-garden','A calm green foreground','A green lawn and clipped planting frame a contemporary stone building.')]),
 dict(slug='water-and-stone', title='The quieter courtyard.', category='outdoor', label='Water & hardscape', cover='water-courtyard', lead='Water, stone and layered planting create a more contemplative kind of outdoors.', text='A raised island planter gives this courtyard its focal point. Water surrounds its clean stone edges, with planting at different heights drawing the eye from the surface to the canopy.', detail='The composition balances the solidity of hardscape with the movement of water and the softness of foliage. It is a study in making a compact outdoor space feel considered from every angle.', tags=['Water features','Stone detailing','Layered greenery'], images=[('water-courtyard','Stillness at the centre','A raised stone planter sits within a water feature, surrounded by leafy planting.')]),
 dict(slug='gardens-after-dark', title='A different kind of evening.', category='lighting', label='Gardens after dark', cover='photo-0063', lead='When daylight fades, the landscape takes on another character.', text='Warm light traces the garden boundaries. Illuminated trees add height and colour, while lawns, pathways and planting remain the centre of the composition.', detail='This collection explores the garden across dusk and night: from softly outlined paths to illuminated edges and welcoming arrival spaces. Lighting makes the layout legible while giving each view its own atmosphere.', tags=['Landscape lighting','Garden boundaries','Evening atmosphere'], images=[('photo-0063','The garden, illuminated','A night garden with warm-lit white fencing, a lawn and an illuminated palm.'),('photo-0060','A ribbon of warm light','Light runs along a white garden fence beside a broad lawn at night.'),('photo-0058','Open space after sunset','A green lawn with trees, garden structures and illuminated boundaries.'),('photo-0061','Following the garden edge','A planted roadside boundary with white fencing and warm lighting.'),('garden-lighting','The transition into evening','A garden at dusk with curving paths, clipped shrubs and illuminated trees.'),('landscape-arrival','A welcoming approach','A road beside landscaped gardens with pathway lighting at dusk.')]),
 dict(slug='lawns-and-open-space', title='Space to simply be.', category='gardens', label='Lawns & open space', cover='estate-lawn', lead='An open lawn gives a property something increasingly rare: breathing room.', text='A broad sweep of green establishes the character of this setting. Palms and planted borders frame the view, allowing the lawn and the building beyond to remain the focus.', detail='The appeal is in the restraint. Clear sightlines, a generous foreground and established greenery give the space a sense of openness without losing its connection to the surrounding landscape.', tags=['Lawn development','Planted borders','Open views'], images=[('estate-lawn','A generous green foreground','An expansive lawn leads toward a white building, with palms along the boundary.')]),
 dict(slug='outdoor-rooms', title='A reason to stay outside.', category='outdoor', label='Pergolas & garden structures', cover='pergola-terrace', lead='A little shelter. A place to sit. A new way to spend time outdoors.', text='A slatted pergola filters the light across a planted terrace. Elsewhere, an illuminated gazebo becomes a focal point within the garden. Each creates a distinct place within the larger landscape.', detail='These views explore how outdoor structures give a space scale and purpose. Planting, seating, shelter and pathways work together to make the outdoors feel inviting.', tags=['Pergolas','Gazebos','Outdoor seating'], images=[('pergola-terrace','Light through the pergola','A slatted pergola above a planted terrace with comfortable outdoor seating.'),('photo-0066','A garden pavilion at night','An illuminated gazebo set within a lawn and bordered by a garden path.'),('photo-0065','An inviting garden edge','A gazebo behind a lit white fence beside a landscaped approach.')]),
 dict(slug='living-green-details', title='Green, in every dimension.', category='planting', label='Planting & living boundaries', cover='photo-0143', lead='From an indoor planter to a green boundary, planting changes how a space feels.', text='Foliage softens an interior edge, climbs a garden boundary and brings rhythm to an exterior wall. These smaller moments of greenery are part of the landscape’s larger story.', detail='A collection of planting details at different scales: vertical layers, palms and an indoor arrangement. Each brings texture and living contrast to the surfaces around it.', tags=['Vertical planting','Boundary planting','Interior greenery'], images=[('photo-0143','A living boundary','Layered green plants arranged vertically along a curved roadside garden boundary.'),('photo-0072','A softer architectural edge','A row of palms and low planting beside a light exterior wall.'),('indoor-planting','A touch of green indoors','Tropical foliage in a long rectangular planter beside large interior windows.')])
]
def story_card(c,i,picture):
 return f'<a class="story-card" data-category="{c["category"]}" href="/projects/{c["slug"]}/" data-reveal><div class="story-image">{picture(c["cover"],c["images"][0][2])}<span class="story-open" aria-hidden="true">↗</span><span class="story-label">{c["label"]}</span></div><div class="story-copy"><span class="story-index">0{i+1} /</span><div><h3>{c["title"]}</h3><p>{c["lead"]}</p></div><span class="story-view">Explore collection ↗</span></div></a>'
def make_portfolio(picture,intro,cta,dialog,button):
 filters=[('all','All collections'),('gardens','Gardens & lawns'),('outdoor','Outdoor living'),('lighting','After dark'),('planting','Planting')]
 cards=''.join(story_card(c,i,picture) for i,c in enumerate(COLLECTIONS))
 index=intro('Selected spaces','Designed to be seen.<br><em>Made to be lived in.</em>','A closer look at our landscape portfolio, curated by design theme. Discover the spaces, details and natural elements that bring the outdoors to life.','Portfolio')
 index+='<section class="wrap portfolio"><div class="filters" role="group" aria-label="Filter portfolio">'+''.join(f'<button class="filter {"active" if i==0 else ""}" data-filter="{v}" aria-pressed="{"true" if i==0 else "false"}">{n}</button>' for i,(v,n) in enumerate(filters))+'</div><div class="portfolio-summary"><span id="gallery-count" aria-live="polite">6 collections · Explore the details within.</span><span>Design / Nature / Craftsmanship</span></div><div class="story-grid-portfolio">'+cards+'</div></section>'+cta()
 pages=[]
 for i,c in enumerate(COLLECTIONS):
  body=f'<div class="wrap breadcrumb"><a href="/projects/">← All collections</a><span>{c["label"]}</span></div><section class="collection-intro wrap"><div class="eyebrow">Portfolio / 0{i+1}</div><h1>{c["title"]}</h1><p>{c["lead"]}</p></section><div class="collection-cover wrap">{picture(c["cover"],c["images"][0][2],eager=True)}</div><section class="section"><div class="wrap collection-narrative"><div><div class="eyebrow">The character of the space</div><h2>Thoughtful details.<br><em>A lasting impression.</em></h2><div class="collection-tags">'+''.join(f'<span>{t}</span>' for t in c['tags'])+f'</div></div><div class="collection-prose"><p>{c["text"]}</p><p>{c["detail"]}</p></div></div></section>'
  body+='<section class="wrap collection-gallery" aria-label="Collection photographs">'
  for j,(n,t,alt) in enumerate(c['images']):
   body+=f'<button class="project-card detail-image" data-reveal aria-label="Enlarge: {escape(t)}"><div class="project-image">{picture(n,alt)}<span class="zoom" aria-hidden="true">↗</span></div><div class="project-meta"><div><h3>{t}</h3><p>{c["label"]}</p></div><span class="project-number">{j+1:02d}</span></div></button>'
  body+='</section>'
  nex=COLLECTIONS[(i+1)%len(COLLECTIONS)]
  body+=f'<section class="next-collection wrap"><div><div class="eyebrow">Continue exploring</div><h2>{nex["title"]}</h2></div>{button("Next collection","/projects/"+nex["slug"]+"/","outline")}</section>'+cta()+dialog()
  pages.append(('/projects/'+c['slug']+'/',c['title'],body))
 return index,pages
